import builtins
import os
import sys

def main():
    special = ['__name__', '__file__', '__doc__', '__package__', '__spec__', '__builtins__', '__debug__', 'reveal_type']
    names = sorted(set(dir(builtins) + special))

    out_lines = [
        "// Generated by tools/gen_py_builtins.py - DO NOT EDIT",
        "#pragma once",
        "",
        "#include <algorithm>",
        "#include <array>",
        "#include <string_view>",
        "",
        "namespace gs::lang {",
        "",
        f"inline constexpr std::array<std::string_view, {len(names)}> PYTHON_BUILTINS = {{"
    ]

    for name in names:
        out_lines.append(f'    "{name}",')

    out_lines.extend([
        "};",
        "",
        "inline bool is_python_builtin(std::string_view name) {",
        "    return std::binary_search(PYTHON_BUILTINS.begin(), PYTHON_BUILTINS.end(), name);",
        "}",
        "",
        "} // namespace gs::lang",
        ""
    ])

    out_path = os.path.join(os.path.dirname(__file__), "..", "src", "lang", "py_builtins.inc")
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(out_lines))
    print(f"Wrote {len(names)} builtins to {out_path}")

if __name__ == "__main__":
    main()
